bool isArrayType(const std::string& type) {
    return type == "list";
}

bool isMapType(const std::string& type) {
    return type == "dict";
}

bool isBufferType(const std::string& type) {
    return type == "buffer";
}

bool isOpaqueHandleType(const std::string& type) {
    return type == "handle";
}

bool isDynamicValueType(const std::string& type) {
    return type == "any";
}

bool parseIntegerMagnitude(const std::string& literal, std::uint64_t& value) {
    const bool hexadecimal = literal.size() >= 2 && literal[0] == '0' &&
                             (literal[1] == 'x' || literal[1] == 'X');
    const auto* begin = literal.data() + (hexadecimal ? 2 : 0);
    const auto* end = literal.data() + literal.size();
    const auto parsed = std::from_chars(begin, end, value, hexadecimal ? 16 : 10);
    return parsed.ec == std::errc{} && parsed.ptr == end;
}

std::int64_t signedBits(std::uint64_t bits) {
    std::int64_t value;
    std::memcpy(&value, &bits, sizeof(value));
    return value;
}

std::int64_t normalizeIntegerBits(std::uint64_t bits, const std::string& type) {
    const auto* numeric = numericType(type);
    if (numeric->width < 64) {
        const auto mask = (std::uint64_t{1} << numeric->width) - 1;
        bits &= mask;
        if (numeric->category == NumericCategory::SignedInteger &&
            (bits & (std::uint64_t{1} << (numeric->width - 1))))
            bits |= ~mask;
    }
    return signedBits(bits);
}

std::string smallestSignedIntegerType(std::uint64_t magnitude, bool negative) {
    for (const unsigned width : {8U, 16U, 32U, 64U}) {
        const auto limit = std::uint64_t{1} << (width - 1);
        if (negative ? magnitude <= limit : magnitude < limit) {
            return "int" + std::to_string(width);
        }
    }
    return {};
}

std::string smallestUnsignedIntegerType(std::uint64_t magnitude) {
    for (const unsigned width : {8U, 16U, 32U}) {
        if (magnitude < (std::uint64_t{1} << width)) {
            return "uint" + std::to_string(width);
        }
    }
    return "uint64";
}

bool nonzeroDecimalLiteral(std::string_view literal) {
    const auto exponent = literal.find_first_of("eE");
    const auto significand = literal.substr(0, exponent);
    return std::any_of(significand.begin(), significand.end(),
                       [](char digit) { return digit >= '1' && digit <= '9'; });
}

std::string classifyFloatingLiteral(const std::string& literal,
                                    const SourceLocation& location) {
    const bool explicitFp64 = literal.size() >= 3 &&
                              literal.compare(literal.size() - 3, 3, "f64") == 0;
    const auto text = explicitFp64 ? literal.substr(0, literal.size() - 3) : literal;
    const auto parseFloat = [&text](auto& value) {
        const auto parsed = std::from_chars(text.data(), text.data() + text.size(), value,
                                            std::chars_format::general);
        return parsed.ec == std::errc{} && parsed.ptr == text.data() + text.size() &&
               std::isfinite(value);
    };
    const bool nonzero = nonzeroDecimalLiteral(text);
    if (!explicitFp64) {
        float value = 0;
        if (parseFloat(value) && (!nonzero || value != 0.0F)) return "fp32";
    }
    double value = 0;
    if (!parseFloat(value) || (nonzero && value == 0.0)) {
        throw DiagnosticError(location,
                              "floating-point literal is outside the finite fp64 range");
    }
    return "fp64";
}

bool floatingConstant(const Expression& expression) {
    if (expression.kind == ExpressionKind::Float) return true;
    if (expression.kind == ExpressionKind::Cast) return isFloatingType(expression.value);
    if (expression.kind == ExpressionKind::Unary && expression.left)
        return floatingConstant(*expression.left);
    return expression.kind == ExpressionKind::Binary && expression.left &&
           expression.right &&
           (floatingConstant(*expression.left) || floatingConstant(*expression.right));
}

bool constantInteger(const Expression& expression, std::int64_t& value) {
    if (expression.kind == ExpressionKind::EnumConstant) {
        const auto parsed = std::from_chars(expression.value.data(),
                                            expression.value.data() + expression.value.size(),
                                            value);
        return parsed.ec == std::errc{} &&
               parsed.ptr == expression.value.data() + expression.value.size();
    }
    if (expression.kind == ExpressionKind::Integer) {
        std::uint64_t magnitude = 0;
        if (!parseIntegerMagnitude(expression.value, magnitude) ||
            magnitude > static_cast<std::uint64_t>(
                            std::numeric_limits<std::int64_t>::max())) {
            return false;
        }
        value = static_cast<std::int64_t>(magnitude);
        return true;
    }
    return false;
}

bool expressionNamePath(const Expression& expression, std::string& name) {
    if (expression.kind == ExpressionKind::Identifier) {
        name = expression.value;
        return true;
    }
    if (expression.kind != ExpressionKind::Member || !expression.left ||
        !expressionNamePath(*expression.left, name)) {
        return false;
    }
    name += "." + expression.value;
    return true;
}

